struct Vertex2 { float x; float y; };
using Triangle = std::array<Vertex2, 3>;

constexpr Triangle make_triangle() {
    return Triangle{{
        Vertex2{-0.5f, -0.5f},
        Vertex2{ 0.5f, -0.5f},
        Vertex2{ 0.0f,  0.5f},
    }};
}

constexpr std::size_t byte_count(const Triangle& vertices) {
    return vertices.size() * sizeof(Vertex2);
}

const auto vertices = study_mesh::make_triangle();
const auto count = vertices.size();
const auto stride = sizeof(vertices[0]);
const auto bytes = study_mesh::byte_count(vertices);

static_assert(CHAR_BIT == 8, "8-bit bytes required");
static_assert(sizeof(float) == 4, "4-byte float required");
static_assert(std::numeric_limits<float>::is_iec559, "IEC 559 float required");
static_assert(std::is_standard_layout<study_mesh::Vertex2>::value,
              "Vertex2 must be standard-layout");
static_assert(offsetof(study_mesh::Vertex2, y) == sizeof(float),
              "y directly after x");
static_assert(sizeof(study_mesh::Vertex2) == 2 * sizeof(float),
              "no padding in Vertex2");

const auto vertices = study_mesh::make_triangle();
const auto* first = vertices.data();
const auto payload_bytes = vertices.size() * sizeof(vertices[0]); // 24
const auto pointer_bytes = sizeof(first); // pointer size, NOT payload size
// std::vector<Vertex2> dynamic;
// sizeof(dynamic) is the control object, NOT its element storage.

std::vector<study_mesh::Vertex2> verts;
verts.reserve(3);                 // size is still 0
for (const auto& vertex : vertices) verts.push_back(vertex);
const auto saved_capacity = verts.capacity();
// Read or copy elements here, before clear().
verts.clear();                    // size=0; no elements to read
const bool retained = verts.capacity() == saved_capacity;

const auto vertices = study_mesh::make_triangle();
std::printf("CPU vertices=%zu stride=%zu bytes=%zu (not uploaded)\n",
            vertices.size(), sizeof(vertices[0]), study_mesh::byte_count(vertices));
